begin;

-- ───────────────── 20261111090000_core_schema.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- TH EDU Companion — core schema
--   categories · branches · videos · portfolios · leads
-- Column names follow the API spec; extra columns marked (+) support the app UI.
-- ═══════════════════════════════════════════════════════════════════════════

-- gen_random_uuid() is built into Postgres 13+ (Supabase runs 15+), so no extension needed.

-- ─── Shared trigger: keep updated_at fresh ──────────────────────────────────
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ─── categories ─────────────────────────────────────────────────────────────
create table public.categories (
  id          smallint generated always as identity primary key,
  code        text not null unique check (code ~ '^[A-Z_]+$'),
  name        text not null,
  icon        text not null,                         -- lucide icon name, e.g. 'pencil-line'
  color       text not null default '#2F6BFF',       -- (+) chip / badge colour
  sort_order  smallint not null default 0            -- (+)
);

comment on table public.categories is 'Course subjects. "ALL" is a UI filter, not a row.';

-- ─── branches (+) ───────────────────────────────────────────────────────────
-- Not in the original spec, but leads/portfolios reference a branch and notifications
-- need its address + map link; a lookup table keeps that data in one place.
create table public.branches (
  code           text primary key check (code ~ '^[A-Z_]+$'),   -- 'XA_LA', 'NGO_THI_NHAM'
  short_code     text not null unique,                          -- 'CS1', 'CS2'
  name           text not null,
  short_address  text not null,
  address        text not null,
  maps_url       text not null
);

-- ─── videos ─────────────────────────────────────────────────────────────────
create table public.videos (
  id                  uuid primary key default gen_random_uuid(),
  title               text not null check (char_length(title) between 3 and 200),
  video_url           text not null check (video_url ~ '^https://'),
  thumbnail_url       text not null check (thumbnail_url ~ '^https://'),
  category_code       text not null references public.categories (code) on update cascade,
  teacher_name        text not null,
  cta_text            text not null,
  created_at          timestamptz not null default now(),

  teacher_avatar_url  text,                                     -- (+)
  tags                text[] not null default '{}',             -- (+) '#ToanTuDuy', …
  cta_link            text,                                     -- (+) thedu://booking?course=…
  is_published        boolean not null default true,            -- (+)
  published_at        timestamptz not null default now(),       -- (+) feed sort key
  updated_at          timestamptz not null default now()        -- (+)
);

-- Keyset pagination: newest first, optionally per category.
create index videos_feed_idx      on public.videos (published_at desc, id desc) where is_published;
create index videos_feed_cat_idx  on public.videos (category_code, published_at desc, id desc) where is_published;

create trigger videos_updated_at before update on public.videos
  for each row execute function public.set_updated_at();

-- ─── portfolios ─────────────────────────────────────────────────────────────
create table public.portfolios (
  id                  uuid primary key default gen_random_uuid(),
  student_name        text not null,
  course_code         text not null references public.categories (code) on update cascade,
  branch_location     text not null references public.branches (code) on update cascade,
  before_image_url    text not null check (before_image_url ~ '^https://'),
  after_image_url     text not null check (after_image_url ~ '^https://'),
  teacher_note        text not null,
  created_at          timestamptz not null default now(),

  display_name        text not null,                            -- (+) 'Bé Gia Bảo'
  class_name          text not null default '',                 -- (+) 'Lớp 1'
  before_label        text not null default 'TRƯỚC',            -- (+) slider overlay
  after_label         text not null default 'SAU',              -- (+)
  teacher_name        text not null,                            -- (+)
  teacher_avatar_url  text,                                     -- (+)
  assessments         jsonb not null default '[]'               -- (+) [{skill, before, after}]
                        check (jsonb_typeof(assessments) = 'array'),
  duration_label      text not null default '',                 -- (+) '2 tháng'
  -- Children's names and work are personal data: never public without written parent consent.
  parent_consent      boolean not null default false,           -- (+)
  is_published        boolean not null default false,           -- (+)
  updated_at          timestamptz not null default now()        -- (+)
);

create index portfolios_public_idx on public.portfolios (course_code, created_at desc)
  where is_published and parent_consent;

create trigger portfolios_updated_at before update on public.portfolios
  for each row execute function public.set_updated_at();

-- ─── leads ──────────────────────────────────────────────────────────────────
create type public.lead_status as enum ('NEW', 'CONTACTED', 'ENROLLED');

create table public.leads (
  id                 uuid primary key default gen_random_uuid(),   -- client may supply → idempotency key
  parent_name        text not null check (char_length(btrim(parent_name)) between 2 and 60),
  phone_number       text not null check (phone_number ~ '^0[35789][0-9]{8}$'),  -- normalised 0xxxxxxxxx
  student_name       text not null check (char_length(btrim(student_name)) between 2 and 60),
  student_age        smallint not null check (student_age between 3 and 12),
  course_code        text not null references public.categories (code) on update cascade,
  branch_location    text not null references public.branches (code) on update cascade,
  quiz_summary       jsonb check (quiz_summary is null or jsonb_typeof(quiz_summary) = 'object'),
  status             public.lead_status not null default 'NEW',
  created_at         timestamptz not null default now(),

  -- (+) human booking code, same formula as the app: 'TH-' + last 6 hex of the uuid
  code               text generated always as ('TH-' || upper(right(replace(id::text, '-', ''), 6))) stored,
  preferred_date     date,                                             -- (+)
  preferred_slot     text,                                             -- (+) slot id, e.g. 'wd-1730'
  source             text not null default 'DIRECT'
                       check (source in ('FEED', 'QUIZ', 'PORTFOLIO', 'DIRECT')),  -- (+)
  zalo_user_id       text,                                             -- (+)
  quiz_answers       jsonb,                                            -- (+)
  notified_at        timestamptz,                                      -- (+) set by the api function
  notification_log   jsonb,                                            -- (+)
  updated_at         timestamptz not null default now()                -- (+)
);

create index leads_created_at_idx   on public.leads (created_at desc);
create index leads_phone_recent_idx on public.leads (phone_number, created_at desc);
create index leads_status_idx       on public.leads (status) where status <> 'ENROLLED';
create index leads_code_idx         on public.leads (code);   -- not unique: 6 hex chars can collide

create trigger leads_updated_at before update on public.leads
  for each row execute function public.set_updated_at();

-- ───────────────── 20261111090100_rls_policies.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Row Level Security
--   • Public (anon + authenticated) READ: categories, branches, published videos,
--     published + consented portfolios.
--   • Public INSERT: leads (NEW only). No public read/update/delete of leads.
--   • Staff (JWT app_metadata.role = 'staff') can read & update leads, manage content.
-- ═══════════════════════════════════════════════════════════════════════════

alter table public.categories  enable row level security;
alter table public.branches    enable row level security;
alter table public.videos      enable row level security;
alter table public.portfolios  enable row level security;
alter table public.leads       enable row level security;

-- Helper: is the caller a centre staff member? (set via auth.users.raw_app_meta_data)
create or replace function public.is_staff()
returns boolean
language sql
stable
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'staff', false);
$$;

-- ─── Public read ────────────────────────────────────────────────────────────
create policy "public read categories"
  on public.categories for select to anon, authenticated
  using (true);

create policy "public read branches"
  on public.branches for select to anon, authenticated
  using (true);

create policy "public read published videos"
  on public.videos for select to anon, authenticated
  using (is_published and published_at <= now());

create policy "public read consented portfolios"
  on public.portfolios for select to anon, authenticated
  using (is_published and parent_consent);

-- ─── Public lead capture ────────────────────────────────────────────────────
-- Prefer the `api` Edge Function (validation, rate limit, notifications); this policy
-- allows direct PostgREST inserts as the spec requires, but only "fresh" rows.
create policy "public insert leads"
  on public.leads for insert to anon, authenticated
  with check (
    status = 'NEW'
    and notified_at is null
    and notification_log is null
    and (preferred_date is null or preferred_date >= current_date)
  );

-- ─── Staff ──────────────────────────────────────────────────────────────────
create policy "staff read leads"
  on public.leads for select to authenticated
  using (public.is_staff());

create policy "staff update leads"
  on public.leads for update to authenticated
  using (public.is_staff())
  with check (public.is_staff());

create policy "staff manage videos"
  on public.videos for all to authenticated
  using (public.is_staff())
  with check (public.is_staff());

create policy "staff manage portfolios"
  on public.portfolios for all to authenticated
  using (public.is_staff())
  with check (public.is_staff());

-- ─── Column privileges ──────────────────────────────────────────────────────
-- RLS limits rows; grants limit columns. Anonymous clients may only write lead input fields.
revoke insert, update, delete on public.leads from anon;
grant insert (id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
              quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers)
  on public.leads to anon;
revoke select on public.leads from anon;

-- ───────────────── 20261111090200_functions.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Database functions (callable via PostgREST RPC and from the `api` Edge Function)
--   get_feed(category, limit, cursor)  → keyset-paginated published videos
--   submit_lead(payload jsonb)         → validated, idempotent, rate-limited lead insert
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── get_feed ───────────────────────────────────────────────────────────────
-- SECURITY INVOKER: RLS on videos still applies (only published rows).
-- Cursor = (published_at, id) of the last item from the previous page.
create or replace function public.get_feed(
  p_category_code   text        default null,
  p_limit           int         default 10,
  p_before_ts       timestamptz default null,
  p_before_id       uuid        default null
)
returns setof public.videos
language sql
stable
security invoker
set search_path = public
as $$
  select v.*
  from public.videos v
  where v.is_published
    and v.published_at <= now()
    and (p_category_code is null or v.category_code = p_category_code)
    and (
      p_before_ts is null
      or (v.published_at, v.id) < (p_before_ts, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
    )
  order by v.published_at desc, v.id desc
  limit least(greatest(coalesce(p_limit, 10), 1), 50);
$$;

grant execute on function public.get_feed(text, int, timestamptz, uuid) to anon, authenticated;

-- ─── submit_lead ────────────────────────────────────────────────────────────
-- SECURITY DEFINER so it can check duplicates / rate limits without granting anon SELECT on leads.
-- Errors are raised with stable SQLSTATE-style hints the API maps to HTTP codes:
--   'VALIDATION:<field>'  → 422,  'RATE_LIMITED' → 429
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  -- Normalise +84xxxxxxxxx → 0xxxxxxxxx
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  -- Validation (mirrors table CHECKs, but with field-level messages)
  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  -- Idempotency: same client-generated id → return the original row.
  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  -- Double-submit guard: same phone + child + course within 30 minutes.
  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  -- Abuse guard: at most 5 leads per phone per 24h.
  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    coalesce(nullif(p ->> 'source', ''), 'DIRECT'),
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers'
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

revoke all on function public.submit_lead(jsonb) from public;
grant execute on function public.submit_lead(jsonb) to anon, authenticated, service_role;

-- ───────────────── 20261112090000_trust.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Trust & social proof — every public claim is backed by data staff control.
--   trust_stats      verified stats; a source note is REQUIRED to publish
--   testimonials     parent videos / letters / notebooks; consent REQUIRED to publish
--   recent_activity  anonymised feed of real recent bookings (powers the TrustTicker)
--   leads.promo_code incentive claimed in the app (e.g. exit-intent e-book)
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── trust_stats ────────────────────────────────────────────────────────────
create table public.trust_stats (
  id            uuid primary key default gen_random_uuid(),
  icon          text not null,                    -- emoji, e.g. '⭐'
  headline      text,                             -- '98%' (null for qualitative claims)
  label         text not null,                    -- 'học sinh cải thiện nét chữ sau 1 tháng'
  source_note   text not null default '',         -- 'Đánh giá đầu vào/ra của 126 HS, T6–T9/2026'
  measured_on   date,
  sort_order    smallint not null default 0,
  is_published  boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  -- A stat cannot go live without saying where it comes from.
  constraint trust_stats_source_required check (not is_published or char_length(btrim(source_note)) >= 10)
);

create trigger trust_stats_updated_at before update on public.trust_stats
  for each row execute function public.set_updated_at();

-- ─── testimonials ───────────────────────────────────────────────────────────
create table public.testimonials (
  id                 uuid primary key default gen_random_uuid(),
  kind               text not null check (kind in ('VIDEO', 'LETTER', 'NOTEBOOK')),
  parent_label       text not null,                       -- 'Mẹ bé Gia Bảo' — as approved by the parent
  course_code        text not null references public.categories (code) on update cascade,
  branch_location    text references public.branches (code) on update cascade,
  quote              text not null default '',
  media_url          text not null check (media_url ~ '^https://'),
  thumbnail_url      text check (thumbnail_url is null or thumbnail_url ~ '^https://'),
  duration_sec       int check (duration_sec is null or duration_sec > 0),
  recorded_on        date,
  -- Written consent from the parent to publish (name, child's work, face/voice).
  consent_confirmed  boolean not null default false,
  is_published       boolean not null default false,
  sort_order         smallint not null default 0,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint testimonials_consent_required check (not is_published or consent_confirmed),
  constraint testimonials_video_thumb check (kind <> 'VIDEO' or thumbnail_url is not null)
);

create index testimonials_public_idx on public.testimonials (kind, sort_order, created_at desc)
  where is_published and consent_confirmed;

create trigger testimonials_updated_at before update on public.testimonials
  for each row execute function public.set_updated_at();

-- ─── RLS ────────────────────────────────────────────────────────────────────
alter table public.trust_stats  enable row level security;
alter table public.testimonials enable row level security;

create policy "public read published stats"
  on public.trust_stats for select to anon, authenticated
  using (is_published);

create policy "public read consented testimonials"
  on public.testimonials for select to anon, authenticated
  using (is_published and consent_confirmed);

create policy "staff manage stats"
  on public.trust_stats for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

create policy "staff manage testimonials"
  on public.testimonials for all to authenticated
  using (public.is_staff()) with check (public.is_staff());

-- ─── leads.promo_code ───────────────────────────────────────────────────────
alter table public.leads
  add column promo_code text check (promo_code is null or promo_code in ('EBOOK_VAO_LOP_1'));

grant insert (promo_code) on public.leads to anon;

-- ─── recent_activity: anonymised real bookings ──────────────────────────────
-- SECURITY DEFINER so the public can see *that* bookings happen without reading leads.
-- Exposes only: masked label ("Phụ huynh T."), course, branch, time. No ids, phones or child data.
create or replace function public.recent_activity(p_limit int default 12)
returns table (
  actor_label  text,
  course_code  text,
  course_name  text,
  branch_code  text,
  branch_name  text,
  created_at   timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select
    'Phụ huynh ' || upper(left(
      (string_to_array(btrim(l.parent_name), ' '))[array_length(string_to_array(btrim(l.parent_name), ' '), 1)],
      1)) || '.' as actor_label,
    l.course_code,
    c.name,
    l.branch_location,
    b.name,
    -- Round to 5 minutes: enough for "x phút trước", not enough to pinpoint someone.
    date_trunc('hour', l.created_at) + floor(extract(minute from l.created_at) / 5) * interval '5 minutes'
  from public.leads l
  join public.categories c on c.code = l.course_code
  join public.branches b on b.code = l.branch_location
  where l.created_at > now() - interval '7 days'
  order by l.created_at desc
  limit least(greatest(coalesce(p_limit, 12), 1), 30);
$$;

revoke all on function public.recent_activity(int) from public;
grant execute on function public.recent_activity(int) to anon, authenticated;

-- ─── submit_lead: accept promo_code ─────────────────────────────────────────
-- Re-declared with the promo field; body otherwise identical to 20261111090200_functions.sql.
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_promo        text := nullif(p ->> 'promo_code', '');
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if v_promo is not null and v_promo not in ('EBOOK_VAO_LOP_1') then
    raise exception 'Mã ưu đãi không hợp lệ' using hint = 'VALIDATION:promo_code';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, zalo_user_id, quiz_answers, promo_code
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    coalesce(nullif(p ->> 'source', ''), 'DIRECT'),
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers',
    v_promo
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

-- ───────────────── 20261113090000_video_publishing.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Video publishing by staff + share links + per-video lead attribution
--   storage bucket  feed-media         public read, staff-only write (videos + cover images)
--   videos          share_slug         short id for share links:  https://<web>/v/<share_slug>
--                   video_path / thumbnail_path / created_by
--   leads           source_ref         which video (id) brought this lead; source 'SHARE_LINK'
--   staff_video_stats()                leads per video, for the staff video list
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── Storage bucket ─────────────────────────────────────────────────────────
-- 200 MB per file here; the project-wide upload limit (Dashboard → Storage → Settings)
-- also applies — it is 50 MB on the Free plan.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'feed-media', 'feed-media', true, 209715200,
  array['video/mp4', 'video/quicktime', 'video/webm', 'image/jpeg', 'image/png', 'image/webp']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Public bucket → anyone can read by URL. Only staff may write.
create policy "staff upload feed media"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'feed-media' and public.is_staff());

create policy "staff update feed media"
  on storage.objects for update to authenticated
  using (bucket_id = 'feed-media' and public.is_staff())
  with check (bucket_id = 'feed-media' and public.is_staff());

create policy "staff delete feed media"
  on storage.objects for delete to authenticated
  using (bucket_id = 'feed-media' and public.is_staff());

-- ─── videos: share slug + storage paths + author ───────────────────────────
alter table public.videos
  add column share_slug     text not null default substr(replace(gen_random_uuid()::text, '-', ''), 1, 10),
  add column video_path     text,
  add column thumbnail_path text,
  add column created_by     uuid default auth.uid() references auth.users (id) on delete set null;

alter table public.videos add constraint videos_share_slug_key unique (share_slug);
alter table public.videos add constraint videos_cta_text_len check (char_length(cta_text) between 3 and 80);

-- ─── leads: attribution ─────────────────────────────────────────────────────
alter table public.leads add column source_ref text check (source_ref is null or char_length(source_ref) <= 64);
create index leads_source_ref_idx on public.leads (source_ref) where source_ref is not null;

alter table public.leads drop constraint if exists leads_source_check;
alter table public.leads add constraint leads_source_check
  check (source in ('FEED', 'QUIZ', 'PORTFOLIO', 'DIRECT', 'SHARE_LINK'));

grant insert (source_ref) on public.leads to anon;

-- ─── staff_video_stats ──────────────────────────────────────────────────────
-- SECURITY INVOKER: non-staff see no leads (RLS) → all counts 0.
create or replace function public.staff_video_stats()
returns table (video_id uuid, lead_count bigint, last_lead_at timestamptz)
language sql
stable
security invoker
set search_path = public
as $$
  select v.id, count(l.id), max(l.created_at)
  from public.videos v
  left join public.leads l on l.source_ref = v.id::text
  group by v.id;
$$;

revoke all on function public.staff_video_stats() from public;
grant execute on function public.staff_video_stats() to authenticated;

-- ─── submit_lead: accept source_ref (+ SHARE_LINK source) ──────────────────
-- Re-declared; otherwise identical to 20261112090000_trust.sql.
create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id           uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_phone        text := regexp_replace(coalesce(p ->> 'phone_number', ''), '[\s.()-]', '', 'g');
  v_parent       text := btrim(coalesce(p ->> 'parent_name', ''));
  v_student      text := btrim(coalesce(p ->> 'student_name', ''));
  v_age          int;
  v_course       text := p ->> 'course_code';
  v_branch       text := p ->> 'branch_location';
  v_promo        text := nullif(p ->> 'promo_code', '');
  v_source       text := coalesce(nullif(p ->> 'source', ''), 'DIRECT');
  v_source_ref   text := nullif(left(coalesce(p ->> 'source_ref', ''), 64), '');
  v_date         date;
  v_existing     public.leads;
  v_row          public.leads;
  v_recent_count int;
begin
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;

  if v_phone !~ '^0[35789][0-9]{8}$' then
    raise exception 'Số điện thoại không hợp lệ' using hint = 'VALIDATION:phone_number';
  end if;
  if char_length(v_parent) not between 2 and 60 or v_parent ~ '[0-9]' then
    raise exception 'Họ tên phụ huynh không hợp lệ' using hint = 'VALIDATION:parent_name';
  end if;
  if char_length(v_student) not between 2 and 60 or v_student ~ '[0-9]' then
    raise exception 'Họ tên của bé không hợp lệ' using hint = 'VALIDATION:student_name';
  end if;
  begin
    v_age := (p ->> 'student_age')::int;
  exception when others then
    v_age := null;
  end;
  if v_age is null or v_age not between 3 and 12 then
    raise exception 'Tuổi của bé không hợp lệ' using hint = 'VALIDATION:student_age';
  end if;
  if not exists (select 1 from public.categories where code = v_course) then
    raise exception 'Khóa học không tồn tại' using hint = 'VALIDATION:course_code';
  end if;
  if not exists (select 1 from public.branches where code = v_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch_location';
  end if;
  if v_promo is not null and v_promo not in ('EBOOK_VAO_LOP_1') then
    raise exception 'Mã ưu đãi không hợp lệ' using hint = 'VALIDATION:promo_code';
  end if;
  if v_source not in ('FEED', 'QUIZ', 'PORTFOLIO', 'DIRECT', 'SHARE_LINK') then
    raise exception 'Nguồn không hợp lệ' using hint = 'VALIDATION:source';
  end if;
  if p ? 'preferred_date' and nullif(p ->> 'preferred_date', '') is not null then
    v_date := (p ->> 'preferred_date')::date;
    if v_date < current_date or v_date > current_date + 60 then
      raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
    end if;
  end if;

  select * into v_existing from public.leads where id = v_id;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select * into v_existing
  from public.leads
  where phone_number = v_phone
    and course_code = v_course
    and lower(student_name) = lower(v_student)
    and created_at > now() - interval '30 minutes'
  order by created_at desc
  limit 1;
  if found then
    return jsonb_build_object('id', v_existing.id, 'code', v_existing.code,
                              'created_at', v_existing.created_at, 'duplicate', true);
  end if;

  select count(*) into v_recent_count
  from public.leads
  where phone_number = v_phone and created_at > now() - interval '24 hours';
  if v_recent_count >= 5 then
    raise exception 'Số điện thoại này đã đăng ký nhiều lần hôm nay' using hint = 'RATE_LIMITED';
  end if;

  insert into public.leads (
    id, parent_name, phone_number, student_name, student_age, course_code, branch_location,
    quiz_summary, preferred_date, preferred_slot, source, source_ref, zalo_user_id, quiz_answers, promo_code
  ) values (
    v_id, v_parent, v_phone, v_student, v_age, v_course, v_branch,
    p -> 'quiz_summary',
    v_date,
    nullif(p ->> 'preferred_slot', ''),
    v_source,
    v_source_ref,
    nullif(p ->> 'zalo_user_id', ''),
    p -> 'quiz_answers',
    v_promo
  )
  returning * into v_row;

  return jsonb_build_object('id', v_row.id, 'code', v_row.code,
                            'created_at', v_row.created_at, 'duplicate', false);
end;
$$;

-- ───────────────── 20261114090000_crm_automation.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- CRM automation: lead lifecycle, appointment time, message log, reminder scheduling
--
--   leads.status        text: NEW → CONFIRMED → REMINDED_24H → REMINDED_2H → COMPLETED_TRIAL → ENROLLED
--                       (+ CONTACTED for manual follow-up, CANCELLED)
--   leads.appointment_time  computed from preferred_date + preferred_slot (Asia/Ho_Chi_Minh)
--   trial_slots         start time of each trial slot (source for appointment_time)
--   crm_logs            every parent message (ZNS / OA / SMS): one active row per (lead, kind) → no double sends
--   crm_due_messages()  which reminders are due now (called by the 15-minute cron)
--   crm_claim_message() / crm_finish_message()   atomic claim + result recording
--   crm_complete_trial() / crm_set_status()      staff actions (checked with is_staff())
-- ═══════════════════════════════════════════════════════════════════════════

-- ─── Trial slots (start times) ──────────────────────────────────────────────
-- Keep in sync with TIME_SLOTS in supabase/functions/_shared/contracts.ts.
create table public.trial_slots (
  id          text primary key,
  label       text not null,
  start_time  time not null,
  kind        text not null check (kind in ('WEEKDAY', 'WEEKEND'))
);

insert into public.trial_slots (id, label, start_time, kind) values
  ('wd-1730', '17:30 – 19:00', '17:30', 'WEEKDAY'),
  ('wd-1900', '19:00 – 20:30', '19:00', 'WEEKDAY'),
  ('we-0800', '08:00 – 09:30', '08:00', 'WEEKEND'),
  ('we-0945', '09:45 – 11:15', '09:45', 'WEEKEND'),
  ('we-1500', '15:00 – 16:30', '15:00', 'WEEKEND');

alter table public.trial_slots enable row level security;
create policy "public read trial slots" on public.trial_slots for select to anon, authenticated using (true);

-- ─── leads.status: enum → text with the full lifecycle ──────────────────────
-- (Column type changes are not allowed while a policy / index references the column.)
drop policy if exists "public insert leads" on public.leads;
drop index if exists public.leads_status_idx;

alter table public.leads alter column status drop default;
alter table public.leads alter column status type text using status::text;
alter table public.leads alter column status set default 'NEW';
alter table public.leads add constraint leads_status_check check (status in (
  'NEW', 'CONTACTED', 'CONFIRMED', 'REMINDED_24H', 'REMINDED_2H', 'COMPLETED_TRIAL', 'ENROLLED', 'CANCELLED'
));
drop type public.lead_status;

create index leads_status_idx on public.leads (status) where status not in ('ENROLLED', 'CANCELLED');

create policy "public insert leads"
  on public.leads for insert to anon, authenticated
  with check (
    status = 'NEW'
    and notified_at is null
    and notification_log is null
    and (preferred_date is null or preferred_date >= current_date)
  );

-- ─── leads: scheduling + trial outcome ──────────────────────────────────────
alter table public.leads
  add column appointment_time    timestamptz,
  add column teacher_note        text check (teacher_note is null or char_length(teacher_note) <= 1000),
  add column staff_note          text check (staff_note is null or char_length(staff_note) <= 1000),
  add column trial_completed_at  timestamptz,
  add column trial_completed_by  uuid references auth.users (id) on delete set null;

create index leads_appointment_idx on public.leads (appointment_time)
  where status in ('CONFIRMED', 'REMINDED_24H', 'REMINDED_2H', 'COMPLETED_TRIAL');

-- appointment_time = preferred_date + slot start, in Vietnam time.
create or replace function public.leads_set_appointment_time()
returns trigger
language plpgsql
as $$
begin
  if new.preferred_date is null or new.preferred_slot is null then
    new.appointment_time := null;
  else
    select (new.preferred_date + s.start_time) at time zone 'Asia/Ho_Chi_Minh'
      into new.appointment_time
    from public.trial_slots s
    where s.id = new.preferred_slot;
  end if;
  return new;
end;
$$;

create trigger leads_appointment_time
  before insert or update of preferred_date, preferred_slot on public.leads
  for each row execute function public.leads_set_appointment_time();

-- Backfill existing leads.
update public.leads set preferred_slot = preferred_slot where preferred_slot is not null;

-- ─── crm_logs ───────────────────────────────────────────────────────────────
create table public.crm_logs (
  id                   uuid primary key default gen_random_uuid(),
  lead_id              uuid not null references public.leads (id) on delete cascade,
  kind                 text not null check (kind in ('CONFIRMATION', 'REMINDER_24H', 'REMINDER_2H', 'POST_TRIAL')),
  channel              text not null check (channel in ('ZNS', 'OA', 'SMS')),
  status               text not null default 'PENDING' check (status in ('PENDING', 'SENT', 'FAILED', 'SKIPPED')),
  attempt              smallint not null default 1,
  provider_message_id  text,
  error                text,
  -- What was sent (template id + params). Contains parent/child names → staff-only (RLS).
  payload              jsonb,
  created_at           timestamptz not null default now(),
  sent_at              timestamptz
);

-- At most one in-flight or successful message per lead and kind → reminders are never sent twice,
-- even if two cron runs overlap. FAILED rows don't count, so a failed send can be retried.
create unique index crm_logs_one_active on public.crm_logs (lead_id, kind) where status in ('PENDING', 'SENT');
create index crm_logs_lead_idx on public.crm_logs (lead_id, created_at desc);

alter table public.crm_logs enable row level security;
create policy "staff read crm logs" on public.crm_logs for select to authenticated using (public.is_staff());
-- No insert/update policies: only the Edge Function (service role) writes logs.

-- ─── Due messages ───────────────────────────────────────────────────────────
-- Rules (p_now injectable for tests):
--   REMINDER_24H  CONFIRMED, appointment in (3h, 24h], booked ≥ 26h ahead (else the confirmation is enough)
--   REMINDER_2H   CONFIRMED or REMINDED_24H, appointment in (0, 2h]
--   POST_TRIAL    COMPLETED_TRIAL, ≥ 2h after the trial, completed within 3 days, 07:00–21:00 Vietnam time
-- Excludes kinds already PENDING/SENT/SKIPPED and kinds that failed 3 times.
create or replace function public.crm_due_messages(p_now timestamptz default now(), p_limit int default 50)
returns table (lead_id uuid, kind text, appointment_time timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  with candidates as (
    select l.id, 'REMINDER_24H'::text as kind, l.appointment_time
    from public.leads l
    where l.status = 'CONFIRMED'
      and l.appointment_time > p_now + interval '3 hours'
      and l.appointment_time <= p_now + interval '24 hours'
      and l.appointment_time - l.created_at >= interval '26 hours'
    union all
    select l.id, 'REMINDER_2H', l.appointment_time
    from public.leads l
    where l.status in ('CONFIRMED', 'REMINDED_24H')
      and l.appointment_time > p_now
      and l.appointment_time <= p_now + interval '2 hours'
    union all
    select l.id, 'POST_TRIAL', l.appointment_time
    from public.leads l
    where l.status = 'COMPLETED_TRIAL'
      and coalesce(l.appointment_time + interval '2 hours', l.trial_completed_at) <= p_now
      and l.trial_completed_at > p_now - interval '3 days'
      and extract(hour from p_now at time zone 'Asia/Ho_Chi_Minh') between 7 and 20
  )
  select c.id, c.kind, c.appointment_time
  from candidates c
  where not exists (
          select 1 from public.crm_logs g
          where g.lead_id = c.id and g.kind = c.kind and g.status in ('PENDING', 'SENT', 'SKIPPED'))
    and (select count(*) from public.crm_logs g
         where g.lead_id = c.id and g.kind = c.kind and g.status = 'FAILED') < 3
  order by c.appointment_time nulls last
  limit greatest(1, least(coalesce(p_limit, 50), 200));
$$;

-- ─── Claim / finish (service role only) ─────────────────────────────────────
-- Claim: insert a PENDING log. Returns its id, or NULL if another run already claimed / sent it.
create or replace function public.crm_claim_message(p_lead_id uuid, p_kind text, p_channel text, p_payload jsonb default null)
returns uuid
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id      uuid;
  v_attempt int;
begin
  -- A run that crashed mid-send leaves PENDING behind: expire it so the message can be retried.
  update public.crm_logs
     set status = 'FAILED', error = coalesce(error, 'timeout: no result recorded')
   where lead_id = p_lead_id and kind = p_kind and status = 'PENDING'
     and created_at < now() - interval '10 minutes';

  select count(*) + 1 into v_attempt
  from public.crm_logs where lead_id = p_lead_id and kind = p_kind and status = 'FAILED';

  insert into public.crm_logs (lead_id, kind, channel, status, attempt, payload)
  values (p_lead_id, p_kind, p_channel, 'PENDING', v_attempt, p_payload)
  on conflict do nothing
  returning id into v_id;

  return v_id;
end;
$$;

-- Record a send attempt that was decided without claiming (e.g. not configured) → stops re-evaluation.
create or replace function public.crm_skip_message(p_lead_id uuid, p_kind text, p_reason text)
returns void
language sql
volatile
security definer
set search_path = public
as $$
  insert into public.crm_logs (lead_id, kind, channel, status, error)
  select p_lead_id, p_kind, 'ZNS', 'SKIPPED', left(p_reason, 500)
  where not exists (select 1 from public.crm_logs
                    where lead_id = p_lead_id and kind = p_kind and status in ('PENDING', 'SENT', 'SKIPPED'));
$$;

-- Finish: record the result; on success advance the lead's status (only from the expected state,
-- so a lead cancelled in the meantime is never moved back).
create or replace function public.crm_finish_message(
  p_log_id uuid, p_status text, p_provider_id text default null, p_error text default null
)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_lead uuid;
  v_kind text;
begin
  if p_status not in ('SENT', 'FAILED') then
    raise exception 'invalid status %', p_status;
  end if;

  update public.crm_logs
     set status = p_status,
         provider_message_id = p_provider_id,
         error = left(p_error, 500),
         sent_at = case when p_status = 'SENT' then now() end
   where id = p_log_id and status = 'PENDING'
  returning lead_id, kind into v_lead, v_kind;

  if p_status = 'SENT' and v_lead is not null then
    update public.leads
       set status = case v_kind
                      when 'CONFIRMATION' then 'CONFIRMED'
                      when 'REMINDER_24H' then 'REMINDED_24H'
                      when 'REMINDER_2H'  then 'REMINDED_2H'
                      else status
                    end
     where id = v_lead
       and ((v_kind = 'CONFIRMATION' and status = 'NEW')
         or (v_kind = 'REMINDER_24H' and status = 'CONFIRMED')
         or (v_kind = 'REMINDER_2H'  and status in ('CONFIRMED', 'REMINDED_24H')));
  end if;
end;
$$;

-- Everything a message template needs, in one call.
create or replace function public.crm_lead_context(p_lead_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', l.id, 'code', l.code, 'status', l.status,
    'parent_name', l.parent_name, 'phone_number', l.phone_number,
    'student_name', l.student_name, 'student_age', l.student_age,
    'course_code', l.course_code, 'course_name', c.name,
    'appointment_time', l.appointment_time,
    'slot_label', s.label,
    'zalo_user_id', l.zalo_user_id,
    'teacher_note', l.teacher_note,
    'trial_completed_at', l.trial_completed_at,
    'branch', jsonb_build_object('code', b.code, 'short_code', b.short_code, 'name', b.name,
                                 'address', b.address, 'maps_url', b.maps_url),
    'latest_video_slug', (select v.share_slug from public.videos v
                          where v.category_code = l.course_code and v.is_published
                          order by v.published_at desc limit 1)
  )
  from public.leads l
  join public.categories c on c.code = l.course_code
  join public.branches b on b.code = l.branch_location
  left join public.trial_slots s on s.id = l.preferred_slot
  where l.id = p_lead_id;
$$;

revoke all on function public.crm_due_messages(timestamptz, int) from public, anon, authenticated;
revoke all on function public.crm_claim_message(uuid, text, text, jsonb) from public, anon, authenticated;
revoke all on function public.crm_skip_message(uuid, text, text) from public, anon, authenticated;
revoke all on function public.crm_finish_message(uuid, text, text, text) from public, anon, authenticated;
revoke all on function public.crm_lead_context(uuid) from public, anon, authenticated;
grant execute on function public.crm_due_messages(timestamptz, int) to service_role;
grant execute on function public.crm_claim_message(uuid, text, text, jsonb) to service_role;
grant execute on function public.crm_skip_message(uuid, text, text) to service_role;
grant execute on function public.crm_finish_message(uuid, text, text, text) to service_role;
grant execute on function public.crm_lead_context(uuid) to service_role;

-- ─── Staff actions (caller's JWT; checked with is_staff()) ──────────────────
create or replace function public.crm_complete_trial(p_lead_id uuid, p_teacher_note text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_note text := btrim(coalesce(p_teacher_note, ''));
  v_row  public.leads;
begin
  if not public.is_staff() then
    raise exception 'Chỉ giáo viên / nhân viên TH EDU được thực hiện thao tác này' using hint = 'FORBIDDEN';
  end if;
  if char_length(v_note) < 10 or char_length(v_note) > 1000 then
    raise exception 'Nhận xét của giáo viên cần 10–1000 ký tự' using hint = 'VALIDATION:teacher_note';
  end if;

  update public.leads
     set status = 'COMPLETED_TRIAL',
         teacher_note = v_note,
         trial_completed_at = now(),
         trial_completed_by = auth.uid()
   where id = p_lead_id
     and status in ('NEW', 'CONTACTED', 'CONFIRMED', 'REMINDED_24H', 'REMINDED_2H')
  returning * into v_row;

  if not found then
    if exists (select 1 from public.leads where id = p_lead_id) then
      raise exception 'Buổi học thử này đã được đánh dấu hoàn thành, hoặc đăng ký đã hủy / đã nhập học'
        using hint = 'CONFLICT';
    end if;
    raise exception 'Không tìm thấy đăng ký' using hint = 'NOT_FOUND';
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'status', v_row.status,
    'trial_completed_at', v_row.trial_completed_at,
    'post_trial_due_at', coalesce(v_row.appointment_time + interval '2 hours', v_row.trial_completed_at)
  );
end;
$$;

create or replace function public.crm_set_status(p_lead_id uuid, p_status text, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_row public.leads;
begin
  if not public.is_staff() then
    raise exception 'Chỉ giáo viên / nhân viên TH EDU được thực hiện thao tác này' using hint = 'FORBIDDEN';
  end if;
  -- Reminder states are set by the system; COMPLETED_TRIAL via crm_complete_trial (needs a note).
  if p_status not in ('NEW', 'CONTACTED', 'CONFIRMED', 'ENROLLED', 'CANCELLED') then
    raise exception 'Trạng thái không hợp lệ' using hint = 'VALIDATION:status';
  end if;

  update public.leads
     set status = p_status,
         staff_note = coalesce(nullif(btrim(p_note), ''), staff_note)
   where id = p_lead_id
  returning * into v_row;
  if not found then
    raise exception 'Không tìm thấy đăng ký' using hint = 'NOT_FOUND';
  end if;

  return jsonb_build_object('id', v_row.id, 'status', v_row.status);
end;
$$;

revoke all on function public.crm_complete_trial(uuid, text) from public, anon;
revoke all on function public.crm_set_status(uuid, text, text) from public, anon;
grant execute on function public.crm_complete_trial(uuid, text) to authenticated;
grant execute on function public.crm_set_status(uuid, text, text) to authenticated;

-- ───────────────── 20261115090000_zalo_tokens.sql ─────────────────
-- ═══════════════════════════════════════════════════════════════════════════
-- Zalo OA token store with safe automatic refresh.
--
-- Zalo rotates tokens: a refresh returns a NEW access token + refresh token, and the old refresh
-- token stops working immediately. Two concurrent refreshes would therefore invalidate the pair.
-- These functions give the Edge Function a single, locked refresh path.
--
-- Server-only: RLS on, no policies, no grants to anon/authenticated → only the service role
-- (Edge Function) and the dashboard SQL editor can touch it.
--
-- One-time bootstrap (SQL editor), with tokens from Zalo's API Explorer / OAuth flow:
--   select public.zalo_token_set('<access_token>', '<refresh_token>', <expires_in_seconds>);
-- ═══════════════════════════════════════════════════════════════════════════

create table public.zalo_oa_tokens (
  id                  smallint primary key default 1 check (id = 1),   -- exactly one row
  access_token        text not null,
  refresh_token       text not null,
  access_expires_at   timestamptz not null,
  refreshed_at        timestamptz not null default now(),
  refresh_lock_until  timestamptz,
  last_error          text,
  last_error_at       timestamptz
);

alter table public.zalo_oa_tokens enable row level security;
revoke all on public.zalo_oa_tokens from anon, authenticated;

-- Current token (no secrets beyond what the sender needs).
create or replace function public.zalo_token_get()
returns table (access_token text, access_expires_at timestamptz, refresh_locked boolean, last_error text)
language sql
stable
security definer
set search_path = public
as $$
  select t.access_token, t.access_expires_at,
         coalesce(t.refresh_lock_until > now(), false), t.last_error
  from public.zalo_oa_tokens t where t.id = 1;
$$;

-- Take the refresh lock. Returns the refresh token if this caller now owns the refresh,
-- NULL if another caller is refreshing (or no tokens are stored).
create or replace function public.zalo_token_begin_refresh(p_lock_seconds int default 60)
returns text
language sql
volatile
security definer
set search_path = public
as $$
  update public.zalo_oa_tokens
     set refresh_lock_until = now() + make_interval(secs => greatest(10, least(p_lock_seconds, 300)))
   where id = 1 and (refresh_lock_until is null or refresh_lock_until <= now())
  returning refresh_token;
$$;

-- Save a freshly issued pair and release the lock.
create or replace function public.zalo_token_store(p_access text, p_refresh text, p_expires_in int)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
begin
  if coalesce(p_access, '') = '' or coalesce(p_refresh, '') = '' or coalesce(p_expires_in, 0) <= 0 then
    raise exception 'invalid token payload';
  end if;
  update public.zalo_oa_tokens
     set access_token = p_access,
         refresh_token = p_refresh,
         access_expires_at = now() + make_interval(secs => p_expires_in),
         refreshed_at = now(),
         refresh_lock_until = null,
         last_error = null,
         last_error_at = null
   where id = 1;
end;
$$;

-- Record a failed refresh and release the lock (the old pair is kept: Zalo rejected the request).
create or replace function public.zalo_token_fail(p_error text)
returns void
language sql
volatile
security definer
set search_path = public
as $$
  update public.zalo_oa_tokens
     set refresh_lock_until = null, last_error = left(p_error, 500), last_error_at = now()
   where id = 1;
$$;

-- Bootstrap / manual replacement (e.g. after re-authorising the OA).
create or replace function public.zalo_token_set(p_access text, p_refresh text, p_expires_in int default 3600)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
begin
  if coalesce(p_access, '') = '' or coalesce(p_refresh, '') = '' then
    raise exception 'access token and refresh token are required';
  end if;
  insert into public.zalo_oa_tokens (id, access_token, refresh_token, access_expires_at)
  values (1, p_access, p_refresh, now() + make_interval(secs => greatest(p_expires_in, 60)))
  on conflict (id) do update
    set access_token = excluded.access_token,
        refresh_token = excluded.refresh_token,
        access_expires_at = excluded.access_expires_at,
        refreshed_at = now(),
        refresh_lock_until = null,
        last_error = null,
        last_error_at = null;
end;
$$;

revoke all on function public.zalo_token_get() from public, anon, authenticated;
revoke all on function public.zalo_token_begin_refresh(int) from public, anon, authenticated;
revoke all on function public.zalo_token_store(text, text, int) from public, anon, authenticated;
revoke all on function public.zalo_token_fail(text) from public, anon, authenticated;
revoke all on function public.zalo_token_set(text, text, int) from public, anon, authenticated;
grant execute on function public.zalo_token_get() to service_role;
grant execute on function public.zalo_token_begin_refresh(int) to service_role;
grant execute on function public.zalo_token_store(text, text, int) to service_role;
grant execute on function public.zalo_token_fail(text) to service_role;
grant execute on function public.zalo_token_set(text, text, int) to service_role;

-- ───────────────── 20261116090000_dashboard_analytics.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Admin dashboard: the data behind each KPI, collected for real (nothing estimated by the app).
--
--   leads.utm_source / utm_medium / utm_campaign   ad link that brought the parent (from the URL)
--   leads.channel        FACEBOOK | TIKTOK | ZALO | REFERRAL | OTHER | UNTRACKED (derived from UTM)
--   leads.enrolled_at    set automatically when a lead becomes ENROLLED
--   course_fees          monthly tuition per course, entered by staff → revenue estimate
--   funnel_events        anonymous app opens / video views (random session id, no personal data)
--   track_event()        anon-callable, at most once per session + kind (+ video)
--   dashboard_summary()  staff-only KPI aggregate for one campus (or all) and a period
--
-- submit_lead() becomes a thin wrapper around the previous implementation (renamed
-- submit_lead_core) that also stores the UTM fields. Later migrations that change lead
-- validation should replace submit_lead_core, not submit_lead.
-- ─────────────────────────────────────────────────────────────────────────────

-- ─── Channel classification ─────────────────────────────────────────────────
create or replace function public.clean_utm(p_value text, p_max int default 100)
returns text
language sql
immutable
as $$
  select nullif(left(regexp_replace(lower(btrim(coalesce(p_value, ''))), '[^a-z0-9._ -]', '', 'g'), p_max), '');
$$;

-- Keep in sync with CHANNEL_LABELS (src/utils/constants.ts) and the UTM guide in supabase/README.md.
create or replace function public.lead_channel(p_source text, p_medium text)
returns text
language sql
immutable
as $$
  select case
    when coalesce(p_medium, '') in ('referral', 'gioi-thieu', 'gioi_thieu')
      or coalesce(p_source, '') in ('referral', 'ref', 'gioi-thieu', 'gioi_thieu')        then 'REFERRAL'
    when coalesce(p_source, '') ~ '^(facebook|instagram|messenger|meta|fb|ig)([._ -]|ads|$)' then 'FACEBOOK'
    when coalesce(p_source, '') ~ '^tiktok'                                               then 'TIKTOK'
    when coalesce(p_source, '') ~ '^zalo'                                                 then 'ZALO'
    when coalesce(p_source, '') = ''                                                      then 'UNTRACKED'
    else 'OTHER'
  end;
$$;

-- ─── leads: attribution + enrolment date ────────────────────────────────────
alter table public.leads
  add column utm_source   text check (utm_source is null or char_length(utm_source) <= 100),
  add column utm_medium   text check (utm_medium is null or char_length(utm_medium) <= 100),
  add column utm_campaign text check (utm_campaign is null or char_length(utm_campaign) <= 150),
  add column enrolled_at  timestamptz;

alter table public.leads
  add column channel text generated always as (public.lead_channel(utm_source, utm_medium)) stored;

create index if not exists leads_created_at_idx on public.leads (created_at desc);
create index if not exists leads_branch_created_idx on public.leads (branch_location, created_at desc);
create index if not exists leads_enrolled_at_idx on public.leads (enrolled_at) where enrolled_at is not null;

create or replace function public.leads_track_enrolment()
returns trigger
language plpgsql
as $$
begin
  if new.status = 'ENROLLED' and old.status is distinct from 'ENROLLED' then
    new.enrolled_at := now();
  elsif new.status <> 'ENROLLED' then
    new.enrolled_at := null;
  end if;
  return new;
end;
$$;

create trigger leads_track_enrolment
  before update of status on public.leads
  for each row execute function public.leads_track_enrolment();

-- Existing students: best available date is the last change to the row.
update public.leads set enrolled_at = updated_at where status = 'ENROLLED' and enrolled_at is null;

-- ─── submit_lead: store UTM ─────────────────────────────────────────────────
alter function public.submit_lead(jsonb) rename to submit_lead_core;
revoke all on function public.submit_lead_core(jsonb) from public, anon, authenticated;

create function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_res jsonb;
begin
  v_res := public.submit_lead_core(p);
  if not coalesce((v_res ->> 'duplicate')::boolean, false) then
    update public.leads
       set utm_source   = public.clean_utm(p ->> 'utm_source'),
           utm_medium   = public.clean_utm(p ->> 'utm_medium'),
           utm_campaign = nullif(left(btrim(coalesce(p ->> 'utm_campaign', '')), 150), '')
     where id = (v_res ->> 'id')::uuid;
  end if;
  return v_res;
end;
$$;

revoke all on function public.submit_lead(jsonb) from public;
grant execute on function public.submit_lead(jsonb) to anon, authenticated, service_role;

-- ─── Tuition (staff-managed) ────────────────────────────────────────────────
create table public.course_fees (
  course_code      text primary key references public.categories (code) on update cascade on delete cascade,
  monthly_fee_vnd  integer not null check (monthly_fee_vnd between 100000 and 50000000),
  updated_at       timestamptz not null default now(),
  updated_by       uuid default auth.uid() references auth.users (id) on delete set null
);

create trigger course_fees_set_updated_at
  before update on public.course_fees
  for each row execute function public.set_updated_at();

alter table public.course_fees enable row level security;
create policy "staff read course fees"   on public.course_fees for select to authenticated using (public.is_staff());
create policy "staff insert course fees" on public.course_fees for insert to authenticated with check (public.is_staff());
create policy "staff update course fees" on public.course_fees for update to authenticated
  using (public.is_staff()) with check (public.is_staff());
create policy "staff delete course fees" on public.course_fees for delete to authenticated using (public.is_staff());
revoke all on public.course_fees from anon;

-- ─── Anonymous funnel events ────────────────────────────────────────────────
-- No foreign key on video_id: deleting a video must not collide with the uniqueness rule below.
create table public.funnel_events (
  id          bigint generated always as identity primary key,
  session_id  uuid not null,
  kind        text not null check (kind in ('APP_OPEN', 'VIDEO_VIEW')),
  video_id    uuid,
  channel     text not null default 'UNTRACKED',
  created_at  timestamptz not null default now()
);

create unique index funnel_events_once_idx
  on public.funnel_events (session_id, kind, coalesce(video_id, '00000000-0000-0000-0000-000000000000'::uuid));
create index funnel_events_created_idx on public.funnel_events (created_at);

-- Written only through track_event(), read only through dashboard_summary().
alter table public.funnel_events enable row level security;
revoke all on public.funnel_events from anon, authenticated;

create or replace function public.track_event(
  p_session_id  uuid,
  p_kind        text,
  p_video_id    uuid default null,
  p_utm_source  text default null,
  p_utm_medium  text default null
)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
begin
  if p_session_id is null or p_kind is null or p_kind not in ('APP_OPEN', 'VIDEO_VIEW') then
    raise exception 'Sự kiện không hợp lệ' using hint = 'VALIDATION:kind';
  end if;
  if p_kind = 'VIDEO_VIEW'
     and (p_video_id is null or not exists (select 1 from public.videos where id = p_video_id and is_published)) then
    return;
  end if;
  -- Flood guard: one browser session cannot add more than 200 rows.
  if (select count(*) from public.funnel_events where session_id = p_session_id) >= 200 then
    return;
  end if;

  insert into public.funnel_events (session_id, kind, video_id, channel)
  values (
    p_session_id,
    p_kind,
    case when p_kind = 'VIDEO_VIEW' then p_video_id end,
    public.lead_channel(public.clean_utm(p_utm_source), public.clean_utm(p_utm_medium))
  )
  on conflict do nothing;
end;
$$;

revoke all on function public.track_event(uuid, text, uuid, text, text) from public;
grant execute on function public.track_event(uuid, text, uuid, text, text) to anon, authenticated;

-- ─── Dashboard aggregate (staff only) ───────────────────────────────────────
-- p_branch: branch code or null (all campuses). p_days: period length (1–365), compared with the
-- period of the same length just before it. Dates are Vietnam time.
create or replace function public.dashboard_summary(
  p_branch  text default null,
  p_days    int default 30,
  p_now     timestamptz default now()
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_days        int := least(greatest(coalesce(p_days, 30), 1), 365);
  v_from        timestamptz := p_now - make_interval(days => v_days);
  v_prev_from   timestamptz := p_now - make_interval(days => 2 * v_days);
  v_today       date := (p_now at time zone 'Asia/Ho_Chi_Minh')::date;
  v_month_start timestamptz := date_trunc('month', p_now at time zone 'Asia/Ho_Chi_Minh') at time zone 'Asia/Ho_Chi_Minh';
  v_result      jsonb;
begin
  if not public.is_staff() then
    raise exception 'Chỉ nhân viên TH EDU được xem số liệu' using hint = 'FORBIDDEN';
  end if;
  if p_branch is not null and not exists (select 1 from public.branches where code = p_branch) then
    raise exception 'Cơ sở không tồn tại' using hint = 'VALIDATION:branch';
  end if;

  with l as (
    select * from public.leads where p_branch is null or branch_location = p_branch
  ),
  cur as (
    select * from l where created_at >= v_from and created_at < p_now
  )
  select jsonb_build_object(
    'generated_at', p_now,
    'period', jsonb_build_object('from', v_from, 'to', p_now, 'days', v_days),
    'leads', jsonb_build_object(
      'current',  (select count(*) from cur),
      'previous', (select count(*) from l where created_at >= v_prev_from and created_at < v_from)
    ),
    'trials_today', jsonb_build_object(
      'scheduled', (select count(*) from l
                     where (appointment_time at time zone 'Asia/Ho_Chi_Minh')::date = v_today
                       and status <> 'CANCELLED'),
      'completed', (select count(*) from l
                     where (appointment_time at time zone 'Asia/Ho_Chi_Minh')::date = v_today
                       and status in ('COMPLETED_TRIAL', 'ENROLLED'))
    ),
    'trial_conversion', jsonb_build_object(
      'completed', (select count(*) from l where trial_completed_at >= v_from and trial_completed_at < p_now),
      'enrolled',  (select count(*) from l where trial_completed_at >= v_from and trial_completed_at < p_now
                                              and status = 'ENROLLED')
    ),
    'revenue', (
      select jsonb_build_object(
        'month_start', v_month_start,
        'enrolled',    count(*),
        'priced',      count(f.course_code),
        'total_vnd',   coalesce(sum(f.monthly_fee_vnd), 0),
        'missing_fee_courses', coalesce(jsonb_agg(distinct e.course_code) filter (where f.course_code is null), '[]'::jsonb)
      )
      from l e
      left join public.course_fees f on f.course_code = e.course_code
      where e.status = 'ENROLLED' and e.enrolled_at >= v_month_start and e.enrolled_at <= p_now
    ),
    'channels', (
      select coalesce(jsonb_object_agg(channel, n), '{}'::jsonb)
      from (select channel, count(*) as n from cur group by channel) s
    ),
    'funnel', jsonb_build_object(
      'app_sessions',   (select count(distinct session_id) from public.funnel_events
                          where kind = 'APP_OPEN' and created_at >= v_from and created_at < p_now),
      'video_sessions', (select count(distinct session_id) from public.funnel_events
                          where kind = 'VIDEO_VIEW' and created_at >= v_from and created_at < p_now),
      'leads',          (select count(*) from cur),
      'trials_done',    (select count(*) from cur where trial_completed_at is not null or status = 'ENROLLED'),
      'enrolled',       (select count(*) from cur where status = 'ENROLLED'),
      'tracking_since', (select min(created_at) from public.funnel_events)
    )
  ) into v_result;

  return v_result;
end;
$$;

revoke all on function public.dashboard_summary(text, int, timestamptz) from public, anon;
grant execute on function public.dashboard_summary(text, int, timestamptz) to authenticated;

-- ───────────────── 20261117090000_admin_accounts.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Admin role + staff account management.
--
--   app_metadata.role = 'admin'   centre owner / manager: everything staff can do, plus managing accounts
--   app_metadata.role = 'staff'   teacher / employee
--
--   is_staff()            now true for staff AND admin (all existing policies keep working)
--   is_admin()            admin only
--   admin_list_staff()    accounts with a role (admin only)
--   admin_set_role()      promote / demote / revoke (admin only; the last admin cannot be removed)
--
-- Creating accounts and resetting passwords need the Auth admin API (service role), so they live in
-- the `api` Edge Function: POST /api/admin/users, POST /api/admin/users/:id/password.
--
-- First admin: create the user in Dashboard → Authentication, then run supabase/sql/make_admin.sql.
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.is_staff()
returns boolean
language sql
stable
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') in ('staff', 'admin'), false);
$$;

create or replace function public.is_admin()
returns boolean
language sql
stable
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false);
$$;

grant execute on function public.is_admin() to anon, authenticated;

create or replace function public.admin_list_staff()
returns table (
  id               uuid,
  email            text,
  role             text,
  display_name     text,
  created_at       timestamptz,
  last_sign_in_at  timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được quản lý tài khoản' using hint = 'FORBIDDEN';
  end if;
  return query
    select u.id, u.email::text, u.raw_app_meta_data ->> 'role',
           nullif(u.raw_user_meta_data ->> 'display_name', ''),
           u.created_at, u.last_sign_in_at
    from auth.users u
    where u.raw_app_meta_data ->> 'role' in ('staff', 'admin')
    order by (u.raw_app_meta_data ->> 'role') = 'admin' desc, u.created_at;
end;
$$;

-- p_role: 'admin' | 'staff' | 'none' (revoke access; the account remains but sees nothing).
create or replace function public.admin_set_role(p_user_id uuid, p_role text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
  v_current text;
  v_admins  int;
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được quản lý tài khoản' using hint = 'FORBIDDEN';
  end if;
  if p_role is null or p_role not in ('admin', 'staff', 'none') then
    raise exception 'Quyền không hợp lệ' using hint = 'VALIDATION:role';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'Không thể tự đổi quyền của chính mình' using hint = 'CONFLICT';
  end if;

  -- Lock the admin rows so two admins demoting each other at once cannot leave zero admins.
  perform 1 from auth.users where raw_app_meta_data ->> 'role' = 'admin' for update;

  select raw_app_meta_data ->> 'role' into v_current from auth.users where id = p_user_id;
  if not found then
    raise exception 'Không tìm thấy tài khoản' using hint = 'NOT_FOUND';
  end if;
  if v_current = 'admin' and p_role <> 'admin' then
    select count(*) into v_admins from auth.users where raw_app_meta_data ->> 'role' = 'admin';
    if v_admins <= 1 then
      raise exception 'Phải còn ít nhất một quản trị viên' using hint = 'CONFLICT';
    end if;
  end if;

  update auth.users
     set raw_app_meta_data = case
           when p_role = 'none' then coalesce(raw_app_meta_data, '{}'::jsonb) - 'role'
           else coalesce(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object('role', p_role)
         end,
         updated_at = now()
   where id = p_user_id;

  return jsonb_build_object('id', p_user_id, 'role', case when p_role = 'none' then null else p_role end);
end;
$$;

revoke all on function public.admin_list_staff() from public, anon;
revoke all on function public.admin_set_role(uuid, text) from public, anon;
grant execute on function public.admin_list_staff() to authenticated;
grant execute on function public.admin_set_role(uuid, text) to authenticated;

-- ───────────────── 20261118090000_admin_only_business.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Business data is admin-only (separate admin area vs teacher / staff area).
--
--   dashboard_summary()   KPIs, revenue, channels, funnel → admins only
--   course_fees           tuition → admins only
--
-- Teachers / staff keep what they need for their work: videos, the trial schedule (leads), CRM actions.
-- dashboard_summary keeps its signature: the previous body becomes dashboard_summary_core (not callable
-- by clients) and dashboard_summary checks is_admin() first.
-- ─────────────────────────────────────────────────────────────────────────────

alter function public.dashboard_summary(text, int, timestamptz) rename to dashboard_summary_core;
revoke all on function public.dashboard_summary_core(text, int, timestamptz) from public, anon, authenticated;

create function public.dashboard_summary(
  p_branch  text default null,
  p_days    int default 30,
  p_now     timestamptz default now()
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được xem số liệu kinh doanh' using hint = 'FORBIDDEN';
  end if;
  return public.dashboard_summary_core(p_branch, p_days, p_now);
end;
$$;

revoke all on function public.dashboard_summary(text, int, timestamptz) from public, anon;
grant execute on function public.dashboard_summary(text, int, timestamptz) to authenticated;

drop policy if exists "staff read course fees"   on public.course_fees;
drop policy if exists "staff insert course fees" on public.course_fees;
drop policy if exists "staff update course fees" on public.course_fees;
drop policy if exists "staff delete course fees" on public.course_fees;

create policy "admin read course fees"   on public.course_fees for select to authenticated using (public.is_admin());
create policy "admin insert course fees" on public.course_fees for insert to authenticated with check (public.is_admin());
create policy "admin update course fees" on public.course_fees for update to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admin delete course fees" on public.course_fees for delete to authenticated using (public.is_admin());

-- ───────────────── 20261119090000_staff_signup_requests.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Self-registration for teachers / staff, approved by an admin.
--
--   1. The login page's "Đăng ký giáo viên / nhân viên" form calls supabase.auth.signUp() with
--      user_metadata { signup_kind: 'staff', display_name, phone, note }.
--      (Requires Dashboard → Authentication → Sign In / Providers → "Allow new users to sign up" = ON.)
--   2. A trigger on auth.users files a PENDING row in staff_requests. The new account has NO role,
--      so RLS gives it nothing until approved. user_metadata is client-controlled and is never used
--      for permissions — the role lives in app_metadata, set only by admin_decide_request().
--   3. Admins see the pending count + list in the admin area and approve (role 'staff') or reject.
--
-- Admin accounts are never self-registered: only a signed-in admin creates them (POST /api/admin/users).
-- ─────────────────────────────────────────────────────────────────────────────

create table public.staff_requests (
  user_id        uuid primary key references auth.users (id) on delete cascade,
  email          text not null,
  display_name   text not null check (char_length(display_name) between 2 and 60),
  phone          text check (phone is null or phone ~ '^0[35789][0-9]{8}$'),
  note           text check (note is null or char_length(note) <= 300),
  status         text not null default 'PENDING' check (status in ('PENDING', 'APPROVED', 'REJECTED')),
  created_at     timestamptz not null default now(),
  decided_at     timestamptz,
  decided_by     uuid references auth.users (id) on delete set null,
  decision_note  text check (decision_note is null or char_length(decision_note) <= 300)
);

create index staff_requests_pending_idx on public.staff_requests (created_at) where status = 'PENDING';

alter table public.staff_requests enable row level security;
-- Applicants can see their own request (to show "đang chờ duyệt" / "bị từ chối" after signing in).
create policy "own staff request" on public.staff_requests for select to authenticated using (user_id = auth.uid());
create policy "admin read staff requests" on public.staff_requests for select to authenticated using (public.is_admin());
revoke insert, update, delete on public.staff_requests from anon, authenticated;

-- ─── Trigger: file a request for sign-ups from the staff form ───────────────
create or replace function public.handle_staff_signup()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Assigned in the body (not here) so any error is caught below and never blocks the sign-up.
  m       jsonb;
  v_name  text;
  v_phone text;
  v_note  text;
begin
  m := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  if m ->> 'signup_kind' is distinct from 'staff' then
    return new;
  end if;
  v_name := left(btrim(coalesce(m ->> 'display_name', '')), 60);
  v_phone := regexp_replace(coalesce(m ->> 'phone', ''), '[\s.()-]', '', 'g');
  v_note := nullif(left(btrim(coalesce(m ->> 'note', '')), 300), '');
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;
  if v_phone !~ '^0[35789][0-9]{8}$' then
    v_phone := null;
  end if;
  if char_length(v_name) < 2 then
    v_name := split_part(coalesce(new.email, 'Nhân viên'), '@', 1);
  end if;

  insert into public.staff_requests (user_id, email, display_name, phone, note)
  values (new.id, coalesce(new.email, ''), left(v_name, 60), v_phone, v_note)
  on conflict (user_id) do nothing;
  return new;
exception when others then
  -- Never block the sign-up itself; the admin can still grant the role manually.
  raise warning 'handle_staff_signup: %', sqlerrm;
  return new;
end;
$$;

create trigger on_auth_user_staff_signup
  after insert on auth.users
  for each row execute function public.handle_staff_signup();

-- ─── Admin: list + decide ───────────────────────────────────────────────────
create or replace function public.admin_list_staff_requests(p_status text default 'PENDING')
returns table (
  user_id            uuid,
  email              text,
  display_name       text,
  phone              text,
  note               text,
  status             text,
  created_at         timestamptz,
  decided_at         timestamptz,
  email_confirmed_at timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được duyệt tài khoản' using hint = 'FORBIDDEN';
  end if;
  return query
    select r.user_id, r.email, r.display_name, r.phone, r.note, r.status, r.created_at, r.decided_at, u.email_confirmed_at
    from public.staff_requests r
    join auth.users u on u.id = r.user_id
    where p_status is null or r.status = p_status
    order by r.created_at desc
    limit 200;
end;
$$;

create or replace function public.admin_decide_staff_request(p_user_id uuid, p_approve boolean, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
  v_req public.staff_requests;
begin
  if not public.is_admin() then
    raise exception 'Chỉ quản trị viên được duyệt tài khoản' using hint = 'FORBIDDEN';
  end if;
  if p_approve is null then
    raise exception 'Thiếu quyết định duyệt / từ chối' using hint = 'VALIDATION:approve';
  end if;

  select * into v_req from public.staff_requests where user_id = p_user_id for update;
  if not found then
    raise exception 'Không tìm thấy yêu cầu' using hint = 'NOT_FOUND';
  end if;
  if v_req.status <> 'PENDING' then
    raise exception 'Yêu cầu này đã được xử lý' using hint = 'CONFLICT';
  end if;

  if p_approve then
    -- Grant 'staff' only; never downgrade an account that is already admin.
    update auth.users
       set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb) || '{"role":"staff"}'::jsonb,
           updated_at = now()
     where id = p_user_id
       and coalesce(raw_app_meta_data ->> 'role', '') <> 'admin';
  end if;

  update public.staff_requests
     set status = case when p_approve then 'APPROVED' else 'REJECTED' end,
         decided_at = now(),
         decided_by = auth.uid(),
         decision_note = nullif(left(btrim(coalesce(p_note, '')), 300), '')
   where user_id = p_user_id;

  return jsonb_build_object('user_id', p_user_id, 'status', case when p_approve then 'APPROVED' else 'REJECTED' end);
end;
$$;

revoke all on function public.handle_staff_signup() from public, anon, authenticated;
revoke all on function public.admin_list_staff_requests(text) from public, anon;
revoke all on function public.admin_decide_staff_request(uuid, boolean, text) from public, anon;
grant execute on function public.admin_list_staff_requests(text) to authenticated;
grant execute on function public.admin_decide_staff_request(uuid, boolean, text) to authenticated;

-- ───────────────── 20261120090000_parent_club_promo.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- CLB Phụ huynh reward: promo code CLB_PHU_HUYNH_100K ("Giảm 100.000đ học phí").
--
-- Parents unlock it in the app by collecting every badge; it travels with the trial booking so staff
-- see it on the lead and apply it at enrolment. (Badges live on the device, so staff confirm the reward —
-- e.g. once per family / phone number.)
--
--   leads.promo_code      now accepts CLB_PHU_HUYNH_100K
--   submit_lead()         validates the promo code itself; submit_lead_core still only knows the
--                         original code, so newer codes are stored right after the insert (same
--                         pattern as the UTM fields).
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.leads drop constraint if exists leads_promo_code_check;
alter table public.leads add constraint leads_promo_code_check
  check (promo_code is null or promo_code in ('EBOOK_VAO_LOP_1', 'CLB_PHU_HUYNH_100K'));

create or replace function public.submit_lead(p jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_res   jsonb;
  v_promo text := nullif(p ->> 'promo_code', '');
  v_core  jsonb := p;
begin
  if v_promo is not null and v_promo not in ('EBOOK_VAO_LOP_1', 'CLB_PHU_HUYNH_100K') then
    raise exception 'Mã ưu đãi không hợp lệ' using hint = 'VALIDATION:promo_code';
  end if;
  -- Codes newer than submit_lead_core are removed before the insert and stored below.
  if v_promo is not null and v_promo <> 'EBOOK_VAO_LOP_1' then
    v_core := p - 'promo_code';
  end if;

  v_res := public.submit_lead_core(v_core);

  if not coalesce((v_res ->> 'duplicate')::boolean, false) then
    update public.leads
       set utm_source   = public.clean_utm(p ->> 'utm_source'),
           utm_medium   = public.clean_utm(p ->> 'utm_medium'),
           utm_campaign = nullif(left(btrim(coalesce(p ->> 'utm_campaign', '')), 150), ''),
           promo_code   = coalesce(promo_code, v_promo)
     where id = (v_res ->> 'id')::uuid;
  end if;
  return v_res;
end;
$$;

revoke all on function public.submit_lead(jsonb) from public;
grant execute on function public.submit_lead(jsonb) to anon, authenticated, service_role;

-- ───────────────── 20261121090000_parent_booking_actions.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Parents manage their own trial bookings (no account): see status, reschedule, cancel.
--
-- Proof of ownership = the booking's id (a random UUID generated on the parent's device and only
-- stored there + shown to staff) AND the phone number used for the booking. Both must match.
--
--   parent_booking_status(id, phone)                 → status / appointment / code
--   parent_reschedule_booking(id, phone, date, slot) → new date + slot; reminders re-armed for the new time
--   parent_cancel_booking(id, phone, reason)         → CANCELLED (no more reminders)
--
-- Every change is appended to leads.staff_note so teachers see what happened in the trial schedule.
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.leads add column if not exists parent_reschedules smallint not null default 0;

create or replace function public.parent_find_lead(p_id uuid, p_phone text)
returns public.leads
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_phone text := regexp_replace(coalesce(p_phone, ''), '[\s.()-]', '', 'g');
  v_row   public.leads;
begin
  if v_phone like '+84%' then
    v_phone := '0' || substr(v_phone, 4);
  end if;
  select * into v_row from public.leads where id = p_id and phone_number = v_phone;
  if not found then
    raise exception 'Không tìm thấy lịch hẹn' using hint = 'NOT_FOUND';
  end if;
  return v_row;
end;
$$;
revoke all on function public.parent_find_lead(uuid, text) from public, anon, authenticated;

create or replace function public.parent_booking_status(p_id uuid, p_phone text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v public.leads := public.parent_find_lead(p_id, p_phone);
begin
  return jsonb_build_object(
    'id', v.id, 'code', v.code, 'status', v.status,
    'preferred_date', v.preferred_date, 'preferred_slot', v.preferred_slot,
    'appointment_time', v.appointment_time,
    'can_change', v.status in ('NEW', 'CONTACTED', 'CONFIRMED', 'REMINDED_24H', 'REMINDED_2H')
                  and coalesce(v.appointment_time, now() + interval '1 day') > now(),
    'reschedules_left', greatest(0, 3 - v.parent_reschedules)
  );
end;
$$;

create or replace function public.parent_reschedule_booking(p_id uuid, p_phone text, p_date date, p_slot text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v       public.leads := public.parent_find_lead(p_id, p_phone);
  v_kind  text;
  v_at    timestamptz;
  v_label text;
  v_old   text;
begin
  if v.status not in ('NEW', 'CONTACTED', 'CONFIRMED', 'REMINDED_24H', 'REMINDED_2H') then
    raise exception 'Lịch hẹn này không thể đổi nữa (đã học thử, đã hủy hoặc đã nhập học)' using hint = 'CONFLICT';
  end if;
  if v.parent_reschedules >= 3 then
    raise exception 'Ba mẹ đã đổi lịch 3 lần. Vui lòng gọi hotline để được hỗ trợ.' using hint = 'RATE_LIMITED';
  end if;
  if p_date is null or p_date < (now() at time zone 'Asia/Ho_Chi_Minh')::date or p_date > (now() at time zone 'Asia/Ho_Chi_Minh')::date + 60 then
    raise exception 'Ngày học thử không hợp lệ' using hint = 'VALIDATION:preferred_date';
  end if;
  v_kind := case when extract(isodow from p_date) in (6, 7) then 'WEEKEND' else 'WEEKDAY' end;
  select (p_date + s.start_time) at time zone 'Asia/Ho_Chi_Minh', s.label into v_at, v_label
  from public.trial_slots s where s.id = p_slot and s.kind = v_kind;
  if v_at is null then
    raise exception 'Khung giờ không hợp lệ cho ngày đã chọn' using hint = 'VALIDATION:preferred_slot';
  end if;
  if v_at < now() + interval '2 hours' then
    raise exception 'Vui lòng chọn giờ học thử cách thời điểm hiện tại ít nhất 2 giờ' using hint = 'VALIDATION:preferred_slot';
  end if;
  if v.preferred_date = p_date and v.preferred_slot = p_slot then
    raise exception 'Đây đã là lịch hiện tại của ba mẹ' using hint = 'VALIDATION:preferred_slot';
  end if;

  v_old := coalesce(to_char(v.appointment_time at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM'), 'chưa có');

  update public.leads
     set preferred_date = p_date,
         preferred_slot = p_slot,
         -- Reminders were for the old time: back to CONFIRMED so the cron reminds again for the new one.
         status = case when status in ('REMINDED_24H', 'REMINDED_2H') then 'CONFIRMED' else status end,
         parent_reschedules = parent_reschedules + 1,
         staff_note = left(concat_ws(E'\n', nullif(staff_note, ''),
                        format('[%s] Phụ huynh đổi lịch: %s → %s', to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI'),
                               v_old, to_char(v_at at time zone 'Asia/Ho_Chi_Minh', 'HH24:MI DD/MM'))), 1000)
   where id = v.id
  returning * into v;

  -- Allow the 24h / 2h reminders to be sent again for the new appointment.
  delete from public.crm_logs where lead_id = v.id and kind in ('REMINDER_24H', 'REMINDER_2H');

  return jsonb_build_object('id', v.id, 'status', v.status, 'preferred_date', v.preferred_date,
                            'preferred_slot', v.preferred_slot, 'appointment_time', v.appointment_time,
                            'slot_label', v_label, 'reschedules_left', greatest(0, 3 - v.parent_reschedules));
end;
$$;

create or replace function public.parent_cancel_booking(p_id uuid, p_phone text, p_reason text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v public.leads := public.parent_find_lead(p_id, p_phone);
  v_reason text := nullif(left(btrim(coalesce(p_reason, '')), 200), '');
begin
  if v.status = 'CANCELLED' then
    return jsonb_build_object('id', v.id, 'status', v.status);
  end if;
  if v.status not in ('NEW', 'CONTACTED', 'CONFIRMED', 'REMINDED_24H', 'REMINDED_2H') then
    raise exception 'Lịch hẹn này không thể hủy (đã học thử hoặc đã nhập học)' using hint = 'CONFLICT';
  end if;
  update public.leads
     set status = 'CANCELLED',
         staff_note = left(concat_ws(E'\n', nullif(staff_note, ''),
                        format('[%s] Phụ huynh tự hủy lịch%s', to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'DD/MM HH24:MI'),
                               coalesce(': ' || v_reason, ''))), 1000)
   where id = v.id
  returning * into v;
  return jsonb_build_object('id', v.id, 'status', v.status);
end;
$$;

revoke all on function public.parent_booking_status(uuid, text) from public;
revoke all on function public.parent_reschedule_booking(uuid, text, date, text) from public;
revoke all on function public.parent_cancel_booking(uuid, text, text) from public;
grant execute on function public.parent_booking_status(uuid, text) to anon, authenticated;
grant execute on function public.parent_reschedule_booking(uuid, text, date, text) to anon, authenticated;
grant execute on function public.parent_cancel_booking(uuid, text, text) to anon, authenticated;

-- ───────────────── 20261122090000_lifecycle_upsell.sql ─────────────────
-- ─────────────────────────────────────────────────────────────────────────────
-- Student lifecycle after a course: completion certificate → teacher review → alumni offer → advisor call.
--
--   enrollments            one course a child is taking (created automatically when a lead becomes ENROLLED)
--   lifecycle_automations  the 4 follow-up messages queued when a teacher completes the course
--
--   Stage            When (09:00 VN)        What
--   COMPLETION_CERT  T+0  (course end date) thank-you + link to the digital certificate
--   TEACHER_REVIEW   T+3                    teacher's qualitative review
--   ALUMNI_DISCOUNT  T+7                    alumni offer for the next course — ONLY if a real offer is configured
--   FINAL_CALL       T+14                   flag the family for an advisor call + gentle reminder (no fake scarcity)
--
-- "student" = the child on the lead (leads has the parent's phone + child's name); there is no separate
-- students table, so enrollments.lead_id plays the role of student_id.
-- Pending follow-ups stop automatically when the family enrols in another course, the course is marked
-- DROPPED, or an advisor records the call.
-- The daily 09:00 job (Edge Function `api` → /api/cron/lifecycle) sends what is due; see
-- supabase/sql/schedule_lifecycle_cron.sql.
-- ─────────────────────────────────────────────────────────────────────────────

create table public.enrollments (
  id                    uuid primary key default gen_random_uuid(),
  lead_id               uuid references public.leads (id) on delete set null,
  student_name          text not null check (char_length(btrim(student_name)) between 2 and 60),
  course_code           text not null references public.categories (code) on update cascade,
  level                 smallint not null default 1 check (level between 1 and 5),
  campus_location       text not null references public.branches (code) on update cascade,
  start_date            date not null default ((now() at time zone 'Asia/Ho_Chi_Minh')::date),
  end_date              date,
  status                text not null default 'ACTIVE' check (status in ('ACTIVE', 'COMPLETED', 'DROPPED')),
  teacher_note          text check (teacher_note is null or char_length(teacher_note) <= 1000),
  certificate_code      text unique,
  completed_at          timestamptz,
  completed_by          uuid references auth.users (id) on delete set null,
  advisor_priority      boolean not null default false,
  advisor_flagged_at    timestamptz,
  advisor_contacted_at  timestamptz,
  advisor_note          text check (advisor_note is null or char_length(advisor_note) <= 500),
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint enrollments_end_after_start check (end_date is null or end_date >= start_date),
  constraint enrollments_completed_fields check (status <> 'COMPLETED' or (end_date is not null and certificate_code is not null))
);

create index enrollments_lead_idx on public.enrollments (lead_id);
create index enrollments_status_idx on public.enrollments (status, end_date);
create index enrollments_priority_idx on public.enrollments (advisor_flagged_at) where advisor_priority;

create trigger enrollments_set_updated_at
  before update on public.enrollments
  for each row execute function public.set_updated_at();

create table public.lifecycle_automations (
  id                   uuid primary key default gen_random_uuid(),
  enrollment_id        uuid not null references public.enrollments (id) on delete cascade,
  stage                text not null check (stage in ('COMPLETION_CERT', 'TEACHER_REVIEW', 'ALUMNI_DISCOUNT', 'FINAL_CALL')),
  scheduled_at         timestamptz not null,
  -- SENDING = claimed by a running job; SKIPPED = could not / should not be sent (reason in error);
  -- CANCELLED = no longer relevant (re-enrolled, dropped, advisor already called).
  status               text not null default 'PENDING' check (status in ('PENDING', 'SENDING', 'SENT', 'FAILED', 'SKIPPED', 'CANCELLED')),
  attempt              smallint not null default 0,
  channel              text check (channel is null or channel in ('ZNS', 'OA')),
  provider_message_id  text,
  error                text,
  sent_at              timestamptz,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint lifecycle_once unique (enrollment_id, stage)
);

create index lifecycle_due_idx on public.lifecycle_automations (scheduled_at) where status in ('PENDING', 'FAILED');

create trigger lifecycle_set_updated_at
  before update on public.lifecycle_automations
  for each row execute function public.set_updated_at();

alter table public.enrollments enable row level security;
alter table public.lifecycle_automations enable row level security;
create policy "staff read enrollments" on public.enrollments for select to authenticated using (public.is_staff());
create policy "staff read lifecycle" on public.lifecycle_automations for select to authenticated using (public.is_staff());
-- Writes go through the functions below (validation + queue in one transaction).
revoke insert, update, delete on public.enrollments from anon, authenticated;
revoke insert, update, delete on public.lifecycle_automations from anon, authenticated;
revoke all on public.enrollments from anon;
revoke all on public.lifecycle_automations from anon;

-- ─── Lead ENROLLED → active enrollment ──────────────────────────────────────
create or replace function public.leads_create_enrollment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status = 'ENROLLED' and old.status is distinct from 'ENROLLED'
     and not exists (select 1 from public.enrollments e
                     where e.lead_id = new.id and e.course_code = new.course_code and e.status = 'ACTIVE') then
    insert into public.enrollments (lead_id, student_name, course_code, campus_location)
    values (new.id, btrim(new.student_name), new.course_code, new.branch_location);
  end if;
  return new;
end;
$$;

create trigger leads_create_enrollment
  after update of status on public.leads
  for each row execute function public.leads_create_enrollment();

-- A new course for the same family → stop the upsell follow-ups of earlier courses.
create or replace function public.enrollments_stop_followups()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.lead_id is not null and new.status = 'ACTIVE' then
    update public.lifecycle_automations a
       set status = 'CANCELLED', error = 'Gia đình đã đăng ký khóa tiếp theo'
      from public.enrollments e
     where a.enrollment_id = e.id and e.lead_id = new.lead_id and e.id <> new.id
       and a.status in ('PENDING', 'FAILED') and a.attempt < 3;
    update public.enrollments
       set advisor_priority = false
     where lead_id = new.lead_id and id <> new.id and advisor_priority;
  end if;
  return new;
end;
$$;

create trigger enrollments_stop_followups
  after insert on public.enrollments
  for each row execute function public.enrollments_stop_followups();

-- ─── Staff actions ──────────────────────────────────────────────────────────

-- Complete a course: certificate + the 4 follow-ups, in one transaction.
create or replace function public.enrollment_complete(
  p_enrollment_id uuid,
  p_teacher_note  text,
  p_end_date      date default null,
  p_level         smallint default null
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_today date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  v_end   date := coalesce(p_end_date, (now() at time zone 'Asia/Ho_Chi_Minh')::date);
  v_note  text := btrim(coalesce(p_teacher_note, ''));
  v_row   public.enrollments;
  v_base  timestamptz;
  v_code  text;
begin
  if not public.is_staff() then
    raise exception 'Chỉ giáo viên / nhân viên TH EDU được thực hiện thao tác này' using hint = 'FORBIDDEN';
  end if;
  if char_length(v_note) < 20 or char_length(v_note) > 1000 then
    raise exception 'Nhận xét cuối khóa cần 20–1000 ký tự' using hint = 'VALIDATION:teacher_note';
  end if;
  if p_level is not null and p_level not between 1 and 5 then
    raise exception 'Cấp độ không hợp lệ' using hint = 'VALIDATION:level';
  end if;

  select * into v_row from public.enrollments where id = p_enrollment_id for update;
  if not found then
    raise exception 'Không tìm thấy khóa học của học viên' using hint = 'NOT_FOUND';
  end if;
  if v_row.status <> 'ACTIVE' then
    raise exception 'Khóa học này đã hoàn thành hoặc đã dừng' using hint = 'CONFLICT';
  end if;
  if v_end < v_row.start_date or v_end > v_today + 30 then
    raise exception 'Ngày kết thúc phải sau ngày bắt đầu và không quá 30 ngày tới' using hint = 'VALIDATION:end_date';
  end if;

  v_code := 'THEDU-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  update public.enrollments
     set status = 'COMPLETED',
         end_date = v_end,
         level = coalesce(p_level, level),
         teacher_note = v_note,
         certificate_code = v_code,
         completed_at = now(),
         completed_by = auth.uid()
   where id = p_enrollment_id
  returning * into v_row;

  -- 09:00 Vietnam time on the end date; if that is already past, the first message is due now.
  v_base := (v_end + time '09:00') at time zone 'Asia/Ho_Chi_Minh';
  insert into public.lifecycle_automations (enrollment_id, stage, scheduled_at) values
    (v_row.id, 'COMPLETION_CERT', greatest(v_base, now())),
    (v_row.id, 'TEACHER_REVIEW',  v_base + interval '3 days'),
    (v_row.id, 'ALUMNI_DISCOUNT', v_base + interval '7 days'),
    (v_row.id, 'FINAL_CALL',      v_base + interval '14 days');

  return jsonb_build_object('id', v_row.id, 'status', v_row.status, 'certificate_code', v_row.certificate_code,
                            'end_date', v_row.end_date, 'level', v_row.level);
end;
$$;

create or replace function public.enrollment_drop(p_enrollment_id uuid, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_row public.enrollments;
begin
  if not public.is_staff() then
    raise exception 'Chỉ giáo viên / nhân viên TH EDU được thực hiện thao tác này' using hint = 'FORBIDDEN';
  end if;
  update public.enrollments
     set status = 'DROPPED', advisor_priority = false,
         advisor_note = coalesce(nullif(left(btrim(coalesce(p_note, '')), 500), ''), advisor_note)
   where id = p_enrollment_id and status <> 'DROPPED'
  returning * into v_row;
  if not found then
    raise exception 'Không tìm thấy khóa học (hoặc đã dừng)' using hint = 'NOT_FOUND';
  end if;
  update public.lifecycle_automations set status = 'CANCELLED', error = 'Học viên dừng học'
   where enrollment_id = p_enrollment_id and status in ('PENDING', 'FAILED') and attempt < 3;
  return jsonb_build_object('id', v_row.id, 'status', v_row.status);
end;
$$;

-- Advisor called the family: clear the flag and stop remaining automated follow-ups.
create or replace function public.enrollment_mark_contacted(p_enrollment_id uuid, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_row public.enrollments;
begin
  if not public.is_staff() then
    raise exception 'Chỉ giáo viên / nhân viên TH EDU được thực hiện thao tác này' using hint = 'FORBIDDEN';
  end if;
  update public.enrollments
     set advisor_priority = false, advisor_contacted_at = now(),
         advisor_note = coalesce(nullif(left(btrim(coalesce(p_note, '')), 500), ''), advisor_note)
   where id = p_enrollment_id and status = 'COMPLETED'
  returning * into v_row;
  if not found then
    raise exception 'Chỉ ghi nhận cuộc gọi cho học viên đã hoàn thành khóa' using hint = 'CONFLICT';
  end if;
  update public.lifecycle_automations set status = 'CANCELLED', error = 'Tư vấn viên đã gọi'
   where enrollment_id = p_enrollment_id and status in ('PENDING', 'FAILED') and attempt < 3;
  return jsonb_build_object('id', v_row.id, 'advisor_contacted_at', v_row.advisor_contacted_at);
end;
$$;

-- ─── Job functions (service role only) ──────────────────────────────────────

create or replace function public.lifecycle_due(p_now timestamptz default now(), p_limit int default 50, p_enrollment_id uuid default null)
returns table (automation_id uuid, enrollment_id uuid, stage text)
language sql
stable
security definer
set search_path = public
as $$
  select a.id, a.enrollment_id, a.stage
  from public.lifecycle_automations a
  join public.enrollments e on e.id = a.enrollment_id
  where a.status in ('PENDING', 'FAILED')
    and a.attempt < 3
    and a.scheduled_at <= p_now
    and e.status = 'COMPLETED'
    and (p_enrollment_id is null or a.enrollment_id = p_enrollment_id)
  order by a.scheduled_at
  limit least(greatest(coalesce(p_limit, 50), 1), 200);
$$;

-- Everything a message needs, in one call.
create or replace function public.lifecycle_context(p_automation_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'automation_id', a.id,
    'stage', a.stage,
    'attempt', a.attempt,
    'enrollment', jsonb_build_object(
      'id', e.id, 'student_name', e.student_name, 'course_code', e.course_code, 'course_name', c.name,
      'level', e.level, 'start_date', e.start_date, 'end_date', e.end_date, 'teacher_note', e.teacher_note,
      'certificate_code', e.certificate_code, 'status', e.status),
    'family', case when l.id is null then null else jsonb_build_object(
      'lead_id', l.id, 'parent_name', l.parent_name, 'phone_number', l.phone_number, 'zalo_user_id', l.zalo_user_id) end,
    'branch', jsonb_build_object('code', b.code, 'name', b.name, 'address', b.address)
  )
  from public.lifecycle_automations a
  join public.enrollments e on e.id = a.enrollment_id
  join public.categories c on c.code = e.course_code
  join public.branches b on b.code = e.campus_location
  left join public.leads l on l.id = e.lead_id
  where a.id = p_automation_id;
$$;

-- Atomic claim: only one job run can send a given follow-up.
create or replace function public.lifecycle_claim(p_automation_id uuid, p_channel text)
returns boolean
language sql
volatile
security definer
set search_path = public
as $$
  with c as (
    update public.lifecycle_automations
       set status = 'SENDING', attempt = attempt + 1, channel = p_channel
     where id = p_automation_id and status in ('PENDING', 'FAILED') and attempt < 3
    returning 1
  )
  select exists (select 1 from c);
$$;

create or replace function public.lifecycle_finish(p_automation_id uuid, p_status text, p_provider_id text default null, p_error text default null)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
begin
  if p_status not in ('SENT', 'FAILED', 'SKIPPED') then
    raise exception 'invalid status %', p_status;
  end if;
  update public.lifecycle_automations
     set status = p_status,
         provider_message_id = p_provider_id,
         error = left(p_error, 500),
         sent_at = case when p_status = 'SENT' then now() else sent_at end
   where id = p_automation_id;
end;
$$;

-- T+14: put the family on the advisor's call list (and note it on the lead for the CRM).
create or replace function public.lifecycle_flag_advisor(p_enrollment_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_row public.enrollments;
begin
  update public.enrollments
     set advisor_priority = true, advisor_flagged_at = coalesce(advisor_flagged_at, now())
   where id = p_enrollment_id and status = 'COMPLETED' and advisor_contacted_at is null
  returning * into v_row;
  if found and v_row.lead_id is not null then
    update public.leads
       set staff_note = left(concat_ws(E'\n', nullif(staff_note, ''),
             format('[%s] Ưu tiên gọi tư vấn khóa tiếp theo (14 ngày sau khi hoàn thành %s)',
                    to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'DD/MM'), v_row.course_code)), 1000)
     where id = v_row.lead_id;
  end if;
end;
$$;

-- ─── Public certificate (by its unguessable code) ───────────────────────────
create or replace function public.get_certificate(p_code text)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'code', e.certificate_code, 'student_name', e.student_name, 'course_code', e.course_code, 'course_name', c.name,
    'level', e.level, 'start_date', e.start_date, 'end_date', e.end_date, 'branch_name', b.name)
  from public.enrollments e
  join public.categories c on c.code = e.course_code
  join public.branches b on b.code = e.campus_location
  where e.certificate_code = upper(btrim(p_code)) and e.status = 'COMPLETED';
$$;

-- ─── Grants ─────────────────────────────────────────────────────────────────
revoke all on function public.leads_create_enrollment() from public, anon, authenticated;
revoke all on function public.enrollments_stop_followups() from public, anon, authenticated;
revoke all on function public.enrollment_complete(uuid, text, date, smallint) from public, anon;
revoke all on function public.enrollment_drop(uuid, text) from public, anon;
revoke all on function public.enrollment_mark_contacted(uuid, text) from public, anon;
grant execute on function public.enrollment_complete(uuid, text, date, smallint) to authenticated;
grant execute on function public.enrollment_drop(uuid, text) to authenticated;
grant execute on function public.enrollment_mark_contacted(uuid, text) to authenticated;

revoke all on function public.lifecycle_due(timestamptz, int, uuid) from public, anon, authenticated;
revoke all on function public.lifecycle_context(uuid) from public, anon, authenticated;
revoke all on function public.lifecycle_claim(uuid, text) from public, anon, authenticated;
revoke all on function public.lifecycle_finish(uuid, text, text, text) from public, anon, authenticated;
revoke all on function public.lifecycle_flag_advisor(uuid) from public, anon, authenticated;
grant execute on function public.lifecycle_due(timestamptz, int, uuid) to service_role;
grant execute on function public.lifecycle_context(uuid) to service_role;
grant execute on function public.lifecycle_claim(uuid, text) to service_role;
grant execute on function public.lifecycle_finish(uuid, text, text, text) to service_role;
grant execute on function public.lifecycle_flag_advisor(uuid) to service_role;

revoke all on function public.get_certificate(text) from public;
grant execute on function public.get_certificate(text) to anon, authenticated;

